 private fun protection(root:LinearLayout,body:View){
  val row=LinearLayout(this).apply {gravity=Gravity.CENTER_VERTICAL}
  row.addView(text("View once · GuardianLab",15f),LinearLayout.LayoutParams(0,-2,1f));root.addView(row)
  status=text("",13f);root.addView(status)
  viewerBody=body;region=ProtectedRegion(this).apply {addView(body,FrameLayout.LayoutParams(-1,-1))};val stack=FrameLayout(this);stack.addView(region,FrameLayout.LayoutParams(-1,-1));startupCover=text("Protected by GuardianLab\n\nPlease remove every recording device.\n\nChecking your surroundings…",20f).apply {gravity=Gravity.CENTER;setBackgroundColor(paper)};stack.addView(startupCover,FrameLayout.LayoutParams(-1,-1));root.addView(stack,LinearLayout.LayoutParams(-1,0,1f))
  notice=ProtectionNotice(this).apply {onPause={monitor?.pause()};onResume={monitor?.resumeProtection()}};root.addView(notice)
  renderProtection()
 }
 private fun covered()=manual || (enabled && latest.coverContent)
 private fun renderProtection(){
  val starting=enabled && latest.state==ProtectionState.INITIALIZING;startupCover?.visibility=if(starting)View.VISIBLE else View.GONE;viewerBody?.visibility=if(starting)View.INVISIBLE else View.VISIBLE;val cover=covered();region?.setProtected(cover);extraRegions.forEach {it.setProtected(cover)}
  status?.text=when {manual->"Hidden manually · tap Hide again to return";!enabled->"GuardianLab off · content is visible";latest.pauseRemainingSeconds>0->"Detection override · ${latest.pauseRemainingSeconds}s · content visible";latest.state==ProtectionState.CLEAR->"Monitoring active · phone and additional-face detection";latest.state==ProtectionState.CAMERA_VIEW_UNAVAILABLE->"Camera view unusable · improve lighting or uncover lens";latest.state==ProtectionState.MONITORING_UNAVAILABLE->protectionReason;else->"$protectionReason · content hidden"}
  val can=enabled && !manual && latest.state in setOf(ProtectionState.POSSIBLE_DEVICE,ProtectionState.DEVICE_CONFIRMED,ProtectionState.WAITING_FOR_CLEAR,ProtectionState.READY_TO_RESUME)
  notice?.render(cover && can,0L,false)
  if(cover){player?.let {if(it.isPlaying)it.pause()};video?.pause()}
 }
