  val loginError=text("",13f).apply {setTextColor(Color.rgb(232,141,158))};var signingIn=false
  fun ready()=identity.text.toString().trim().matches(Regex("@?[a-zA-Z0-9_]{3,24}")) && password.length() in 10..128
  val signIn=button("Sign in"){};fun syncLogin(){signIn.isEnabled=ready() && !signingIn;signIn.backgroundTintList=android.content.res.ColorStateList.valueOf(if(signIn.isEnabled)accent else Color.rgb(84,24,39));signIn.setTextColor(if(signIn.isEnabled)Color.WHITE else Color.rgb(168,135,144))}
  signIn.setOnClickListener {if(ready()&&!signingIn){signingIn=true;syncLogin();loginError.text="";val address=prefs.getString("server","https://192.168.1.171:8766")!!;val who=identity.text.toString().trim();val secret=password.text.toString();net.execute {try{val result=ChatApi(address).request("/login",JSONObject().put("identity",who).put("password",secret));main.post {prefs.edit().putString("server",address).putString("token",result.getString("token")).putString("id",result.getString("id")).putString("name",result.getString("name")).apply();profileCache.clear();alertsPrimed=false;alertLatest.clear();password.text.clear();showPeople()}}catch(e:Exception){main.post {loginError.text=if(e.message?.contains("Incorrect account or password")==true)"Account not found or password incorrect. Check your details, or choose Sign up." else e.message?:"Could not sign in"}}finally{main.post {signingIn=false;syncLogin()}}}}}
  val watcher=object:android.text.TextWatcher {override fun beforeTextChanged(s:CharSequence?,start:Int,count:Int,after:Int){};override fun onTextChanged(s:CharSequence?,start:Int,before:Int,count:Int){loginError.text="";syncLogin()};override fun afterTextChanged(s:android.text.Editable?) {}};identity.addTextChangedListener(watcher);password.addTextChangedListener(watcher);syncLogin()
  val actions=LinearLayout(this);actions.addView(signIn,LinearLayout.LayoutParams(0,-2,1f));actions.addView(button("Sign up"){showSetup(!signup)},LinearLayout.LayoutParams(0,-2,1f).apply {marginStart=dp(8)});root.addView(actions);root.addView(loginError)
  if(!signup){setContentView(root);return}
