  root.addView(server);root.addView(invite);root.addView(name)
  val nickname=field("Your @nickname");root.addView(nickname);val connect=button("Sign up"){}
  connect.setOnClickListener {
   connect.isEnabled=false;val address=server.text.toString().trim();val code=invite.text.toString().trim();val who=name.text.toString().trim()
   async {try{val result=ChatApi(address).request("/register",JSONObject().put("invite",code).put("name",who).put("nickname",nickname.text.toString().trim()));main.post {prefs.edit().putString("server",address).putString("token",result.getString("token")).putString("id",result.getString("id")).putString("name",result.getString("name")).apply();showPeople()}}finally{main.post {connect.isEnabled=true}}}
  };root.addView(connect);root.addView(text("No phone number required. Your unique ID is stored on this device. Set a sign-in password in your profile to return to this same account.",13f));setContentView(root)
