  root.addView(text("Chat list",14f));val scroll=object:ScrollView(this){var pullStart=0f;var pullAtTop=false;override fun dispatchTouchEvent(event:android.view.MotionEvent):Boolean {when(event.actionMasked){android.view.MotionEvent.ACTION_DOWN->{pullStart=event.y;pullAtTop=scrollY==0};android.view.MotionEvent.ACTION_UP->{if(pullAtTop && event.y-pullStart>dp(75)){pullAtTop=false;fetchPeople();toast("Chat list refreshed");val cancel=android.view.MotionEvent.obtain(event);cancel.action=android.view.MotionEvent.ACTION_CANCEL;super.dispatchTouchEvent(cancel);cancel.recycle();return true};pullAtTop=false};android.view.MotionEvent.ACTION_CANCEL->{pullAtTop=false}};return super.dispatchTouchEvent(event)}};people=LinearLayout(this).apply {orientation=LinearLayout.VERTICAL};scroll.addView(people);scroll.background=boundary();root.addView(scroll,LinearLayout.LayoutParams(-1,0,1f))
