 private fun fetchPeople(){if(fetching)return;fetching=true;val gen=generation
  net.execute {try{val list=api().request("/users").getJSONArray("users");main.post {if(screen=="people"&&generation==gen){people?.removeAllViews();if(list.length()==0)people?.addView(text("No contacts yet. Add someone using their contact code."));for(i in 0 until list.length()){val u=list.getJSONObject(i);if(profileCache[u.getString("id")]?.optInt("profile_version")!=u.optInt("profile_version"))profileCache.remove(u.getString("id"));val card=LinearLayout(this).apply {orientation=LinearLayout.VERTICAL;setPadding(dp(8),dp(6),dp(8),dp(6));background=GradientDrawable().apply {setColor(Color.rgb(48,48,48));cornerRadius=0f};minimumHeight=dp(56);val heading=LinearLayout(this@MainActivity).apply {gravity=Gravity.CENTER_VERTICAL};heading.addView(profileIcon(u.getString("id"),u.getString("name")),LinearLayout.LayoutParams(dp(36),dp(36)));heading.addView(text(u.getString("name"),18f).apply {typeface=android.graphics.Typeface.DEFAULT_BOLD;maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.END},LinearLayout.LayoutParams(0,-2,1f));if(u.optInt("unread")>0)heading.addView(text(if(u.optInt("unread")>99)"99+" else u.optInt("unread").toString(),11f).apply {gravity=Gravity.CENTER;setPadding(0,0,0,0);setTextColor(Color.WHITE);background=GradientDrawable().apply {setColor(accent);cornerRadius=dp(50).toFloat()}},LinearLayout.LayoutParams(dp(22),dp(22)).apply {marginEnd=dp(6)});addView(heading);addView(text("@"+u.optString("nickname",u.getString("id")),12f).apply {setTextColor(Color.LTGRAY)});contentDescription="${u.getString("name")} · ${u.getString("id")}";setOnClickListener {peer=u.getString("id");peerName=u.getString("name");showChat()}};people?.addView(card,LinearLayout.LayoutParams(-1,-2));people?.addView(View(this).apply {setBackgroundColor(Color.DKGRAY)},LinearLayout.LayoutParams(-1,dp(1)))}}}}catch(e:Exception){main.post {if(screen=="people")people?.let {it.removeAllViews();it.addView(text("Server unavailable. Check the Mac and Wi-Fi."))}}}finally{main.post {fetching=false}}}
 }
 private fun showChat(){closeOnce();releasePlayback();screen="chat";firstMessageLoad=true;unreadShown=false;generation++;after=0
  val root=root(peerName){showPeople()};val header=root.getChildAt(0) as LinearLayout;header.background=boundary().apply {setColor(Color.rgb(48,48,48))};header.getChildAt(1).setOnClickListener {showProfile(peer)};header.addView(profileIcon(peer,peerName),2,LinearLayout.LayoutParams(dp(36),dp(36)));scroller=ScrollView(this);messages=LinearLayout(this).apply {orientation=LinearLayout.VERTICAL};scroller!!.addView(messages);scroller!!.background=boundary();scroller!!.setPadding(dp(6),0,dp(6),0)
