 private fun fetchMessages(){if(fetching || peer.isEmpty())return;fetching=true;val gen=generation;val target=peer;val cursor=after
  net.execute {try{val response=api().request("/messages?peer=${URLEncoder.encode(target,"UTF-8")}&after=$cursor");val list=response.getJSONArray("messages");main.post {if(screen=="chat"&&generation==gen){val entry=firstMessageLoad;firstMessageLoad=false;val unread=response.optInt("unread_count");for(i in 0 until list.length()){val msg=list.getJSONObject(i);if(entry && !unreadShown && unread>0 && msg.getString("recipient")==prefs.getString("id","") && msg.optLong("read_at")==0L){unreadShown=true;messages?.addView(text("──── $unread unread message${if(unread==1)"" else "s"} ────",13f).apply {gravity=Gravity.CENTER;setTextColor(Color.LTGRAY)})};after=maxOf(after,msg.getLong("id"));addMessage(msg)};refreshReceipts(target,gen);if(list.length()>0){val received=org.json.JSONArray();for(i in 0 until list.length()){val m=list.getJSONObject(i);if(m.getString("recipient")==prefs.getString("id",""))received.put(m.getLong("id"))};if(received.length()>0)async {api().request("/delivered",JSONObject().put("ids",received))};scroller?.post {scroller?.fullScroll(View.FOCUS_DOWN)};if(foreground){val through=after;async {api().request("/read",JSONObject().put("peer",target).put("through",through))};getSystemService(android.app.NotificationManager::class.java).cancel(target.hashCode())}}}}}catch(e:Exception){main.post {if(screen=="chat"&&generation==gen)status?.text="Connection lost · retrying. ${if(enabled)"GuardianLab remains enabled." else "GuardianLab is off."}"}}finally{main.post {fetching=false}}}
 }
 private fun addMessage(msg:JSONObject){
  val own=msg.getString("sender")==prefs.getString("id","");val client=msg.optString("client_id");if(own && !msg.optBoolean("pending")){pendingRows.remove(client)?.let {messages?.removeView(it)};pendingDots.remove(client)};val outer=LinearLayout(this).apply {orientation=LinearLayout.VERTICAL;gravity=if(own)Gravity.END else Gravity.START};val box=LinearLayout(this).apply {orientation=LinearLayout.VERTICAL;setPadding(dp(10),dp(6),dp(10),dp(6));background=GradientDrawable().apply {setColor(if(own)Color.rgb(101,20,38) else Color.rgb(36,36,36));cornerRadius=dp(18).toFloat()}}
  outer.addView(text(if(own)"You" else peerName,12f).apply {typeface=android.graphics.Typeface.create("sans-serif",android.graphics.Typeface.ITALIC);setTextColor(Color.LTGRAY)});val content=msg.optString("text");if(content.isNotBlank())box.addView(text(content,16f).apply {setPadding(0,0,0,0);maxWidth=resources.displayMetrics.widthPixels-dp(80)})
  if(msg.optInt("view_once")==1){val used=msg.optInt("opened")==1;box.addView(if(own)text("View-once content sent",15f) else button(if(used)"View once · opened" else "Open protected view once"){if(!used)openOnce(msg)}.apply {isEnabled=!used})}
  if(!msg.isNull("fileid") && msg.optInt("view_once")!=1){val filename=msg.getString("filename");val visual=msg.optString("mime").let {it.startsWith("image/")||it.startsWith("video/")};if(visual)addMediaThumbnail(msg,box);box.addView(movingFilename(filename),LinearLayout.LayoutParams(dp(220),dp(22)));if(!visual)box.addView(button("Open"){openAttachment(msg)},LinearLayout.LayoutParams(dp(100),dp(42)))}
  val time=java.text.DateFormat.getTimeInstance(java.text.DateFormat.SHORT).format(java.util.Date(msg.getLong("time")));outer.addView(box,LinearLayout.LayoutParams(-2,-2));val footer=LinearLayout(this).apply {gravity=Gravity.CENTER_VERTICAL};footer.addView(text(time,11f).apply {typeface=android.graphics.Typeface.create("sans-serif",android.graphics.Typeface.ITALIC);setTextColor(Color.LTGRAY)});if(own){val dot=View(this);paintReceipt(dot,msg,msg.optBoolean("pending"));footer.addView(dot,LinearLayout.LayoutParams(dp(7),dp(7)).apply {marginEnd=dp(8)});if(msg.optBoolean("pending")){pendingRows[client]=outer;pendingDots[client]=dot}else receiptDots[msg.getLong("id")]=dot};outer.addView(footer,LinearLayout.LayoutParams(-2,-2))
  messages?.addView(View(this).apply {setBackgroundColor(Color.rgb(45,45,45))},LinearLayout.LayoutParams(-1,dp(1)).apply {topMargin=dp(6)});messages?.addView(outer,LinearLayout.LayoutParams(-1,-2).apply {topMargin=dp(6);leftMargin=if(own)dp(30) else 0;rightMargin=if(own)0 else dp(30)})
 }
