 private fun readLimited(uri:Uri,limit:Int):ByteArray {val input=contentResolver.openInputStream(uri)?:error("Could not read file");return input.use {val out=java.io.ByteArrayOutputStream();val buffer=ByteArray(65536);while(true){val n=it.read(buffer);if(n<0)break;check(out.size()+n<=limit){"Video limit is 30 MB; other files 8 MB"};out.write(buffer,0,n)};out.toByteArray()}}
 private fun send(content:String="",uri:Uri?=null,file:File?=null,filename:String?=null,mime:String?=null){
  if(sending || peer.isEmpty())return;sending=true;sendButton?.isEnabled=false;val target=peer;val gen=generation;val id=UUID.randomUUID().toString();val once=onceChoice?.isChecked==true
  addMessage(JSONObject().put("sender",prefs.getString("id","")).put("text",if(once)"" else content.ifEmpty {filename?:"Attachment"}).put("id",-1).put("client_id",id).put("time",System.currentTimeMillis()).put("view_once",if(once)1 else 0).put("pending",true));scroller?.post {scroller?.fullScroll(View.FOCUS_DOWN)}
  async {try{
   val body=JSONObject().put("peer",target).put("text",content).put("client_id",id).put("view_once",once)
   if(uri!=null || file!=null){val limit=if(mime?.startsWith("video/")==true)30*1024*1024 else 8*1024*1024;val data=if(uri!=null)readLimited(uri,limit) else file!!.readBytes();check(data.size<=limit){"Video limit is 30 MB; other files 8 MB"};body.put("data",android.util.Base64.encodeToString(data,android.util.Base64.NO_WRAP)).put("filename",filename?:"attachment").put("mime",mime?:"application/octet-stream")}
   api().request("/messages",body);main.post {if(generation==gen){pendingDots[id]?.let {paintReceipt(it,JSONObject(),false)};if(draft?.text.toString().trim()==content)draft?.text?.clear();toast("Sent");fetchMessages()}}
  }catch(e:Exception){main.post {pendingRows.remove(id)?.let {messages?.removeView(it)};pendingDots.remove(id)};throw e}finally{file?.delete();main.post {sending=false;sendButton?.isEnabled=true}}}
 }
 private fun paintReceipt(dot:View,m:JSONObject,sending:Boolean=false){val state=if(sending)"sending" else if(m.optLong("read_at")>0)"read" else if(m.optLong("delivered_at")>0)"delivered" else "sent";val color=when(state){"read"->Color.rgb(230,69,112);"delivered"->Color.rgb(101,20,38);else->Color.WHITE};dot.contentDescription=state;dot.background=GradientDrawable().apply {shape=GradientDrawable.OVAL;setColor(if(sending)Color.TRANSPARENT else color);setStroke(dp(1),color)}}
