 private fun clearPreview(){pendingSend=null;val cleanup=previewCleanup;previewCleanup=null;cleanup?.invoke()}
 private fun previewSend(uri:Uri?=null,file:File?=null,filename:String,mime:String?){
  val target=peer;val source=uri?:Uri.fromFile(file!!);var submitted=false;var audio:MediaPlayer?=null
  val body=LinearLayout(this).apply {orientation=LinearLayout.VERTICAL;setPadding(dp(16),dp(8),dp(16),dp(8));addView(text(filename))}
  var previewVideo:VideoView?=null
  try{when {
   mime?.startsWith("image/")==true->{val bitmap=contentResolver.openInputStream(source)?.use {BitmapFactory.decodeStream(it,null,BitmapFactory.Options().apply {inSampleSize=4})};body.addView(ImageView(this).apply {setImageBitmap(bitmap);adjustViewBounds=true;scaleType=ImageView.ScaleType.FIT_CENTER},LinearLayout.LayoutParams(-1,dp(150)))}
   mime?.startsWith("video/")==true->{previewVideo=VideoView(this).apply {setVideoURI(source);setMediaController(MediaController(this@MainActivity).also {it.setAnchorView(this)})};body.addView(previewVideo,LinearLayout.LayoutParams(-1,dp(150)))}
   mime?.startsWith("audio/")==true->{body.addView(button("Play / pause preview"){try{if(audio==null){audio=MediaPlayer().apply {setDataSource(this@MainActivity,source);prepare()}};audio?.let {if(it.isPlaying)it.pause() else it.start()}}catch(e:Exception){toast("Audio preview unavailable")}})}
   else->body.addView(text("File ready to send"))
  }}catch(e:Exception){body.addView(text("Preview unavailable · you can still send this file"))}
  clearPreview()
  body.background=GradientDrawable().apply {setColor(Color.rgb(38,38,38));cornerRadius=dp(18).toFloat();setStroke(dp(1),Color.DKGRAY)}
  val actions=LinearLayout(this).apply {gravity=Gravity.CENTER_VERTICAL}
  val choice=onceToggle(onceChoice?.isChecked==true){checked->onceChoice?.isChecked=checked}
  actions.addView(choice,LinearLayout.LayoutParams(dp(32),dp(32)))
  actions.addView(button("Cancel"){clearPreview()})
  val submit={if(peer==target && screen=="chat"){submitted=true;send(content=draft?.text.toString().trim(),uri=uri,file=file,filename=filename,mime=mime);clearPreview()}}
  actions.addView(button("Send"){submit()});body.addView(actions)
  composer?.addView(body,0,LinearLayout.LayoutParams(-1,-2))
  pendingSend=submit
  previewCleanup={audio?.release();previewVideo?.stopPlayback();composer?.removeView(body);if(!submitted)file?.delete()}

 }
 override fun onActivityResult(requestCode:Int,resultCode:Int,data:Intent?){super.onActivityResult(requestCode,resultCode,data)
  if(resultCode!=RESULT_OK)return
  if(requestCode==23){val words=data?.getStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS)?.firstOrNull()?:return;draft?.let {val start=maxOf(0,it.selectionStart);val end=maxOf(start,it.selectionEnd);it.text.replace(start,end,words)};return}
  if(requestCode==22){val uri=data?.data?:return;val gen=generation;async {val bitmap=contentResolver.openInputStream(uri)?.use {BitmapFactory.decodeStream(it,null,BitmapFactory.Options().apply {inSampleSize=4})}?:error("Unable to read photo");val edge=minOf(bitmap.width,bitmap.height);val square=Bitmap.createBitmap(bitmap,(bitmap.width-edge)/2,(bitmap.height-edge)/2,edge,edge);val small=Bitmap.createScaledBitmap(square,256,256,true);val out=java.io.ByteArrayOutputStream();small.compress(Bitmap.CompressFormat.JPEG,85,out);main.post {if(screen=="profile"&&generation==gen){profilePhotoDraft=android.util.Base64.encodeToString(out.toByteArray(),android.util.Base64.NO_WRAP);profileDraftImage?.setImageBitmap(small);profileDirtyCheck?.invoke()}}};return}
  if(requestCode==20){val uri=data?.data?:return;var name="attachment";contentResolver.query(uri,arrayOf(OpenableColumns.DISPLAY_NAME),null,null,null)?.use {if(it.moveToFirst())name=it.getString(0)};previewSend(uri=uri,filename=name,mime=contentResolver.getType(uri))}
  if(requestCode==21){val out=data?.data?:return;val source=exportFile?:return;async {contentResolver.openOutputStream(out)?.use {sink->source.inputStream().use {it.copyTo(sink)}}?:error("Could not save");main.post {toast("Saved outside GuardianLab protection")}}}
 }
