   val item=api().request("/open",JSONObject().put("message_id",msg.getLong("id")))
   val f=File(cacheDir,"media-once-${item.getLong("id")}")
   try{if(!item.isNull("fileid"))api().download(item.getString("fileid"),f,item.getString("view_token"))
    main.post {if(gen==generation && foreground){viewOnceId=item.getLong("id");enabled=true;manual=false;latest=ProtectionDecision(ProtectionState.INITIALIZING,true);currentFile=f;opened=item;showViewer(item,f)}else {f.delete();async {api().request("/close",JSONObject().put("message_id",item.getLong("id")))}}}
   }catch(e:Exception){f.delete();api().request("/close",JSONObject().put("message_id",item.getLong("id")));throw e}
  }
