 private fun showViewer(msg:JSONObject,f:File){screen="viewer";generation++;releasePlayback();val root=root(if(viewOnceId!=null)"View-once content" else msg.getString("filename")){showChat()};val body=LinearLayout(this).apply {orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER}
  val mime=msg.optString("mime")
  if(viewOnceId!=null && msg.optString("text").isNotEmpty())body.addView(text(msg.getString("text"),18f))
  try{
   when {
    mime.startsWith("image/")->{val options=BitmapFactory.Options().apply {inJustDecodeBounds=true};BitmapFactory.decodeFile(f.absolutePath,options);options.inJustDecodeBounds=false;options.inSampleSize=maxOf(1,maxOf(options.outWidth,options.outHeight)/1600);val bmp=BitmapFactory.decodeFile(f.absolutePath,options)?:error("Unsupported image");body.addView(ImageView(this).apply {setImageBitmap(bmp);adjustViewBounds=true;contentDescription="Received image"},LinearLayout.LayoutParams(-1,0,1f))}
    mime.startsWith("video/")->{video=VideoView(this).apply {setVideoPath(f.absolutePath);setOnPreparedListener {it.setLooping(false)};if(viewOnceId==null)setMediaController(MediaController(this@MainActivity).also {it.setAnchorView(this)})};body.addView(video,LinearLayout.LayoutParams(-1,0,1f));body.addView(button("Play / pause"){if(!covered()){if(video!!.isPlaying)video!!.pause() else video!!.start()}})}
    mime.startsWith("audio/")->{player=MediaPlayer().apply {setDataSource(f.absolutePath);prepare()};body.addView(text("Voice note / audio",23f));body.addView(button("Play / pause"){if(!covered())player?.let {if(it.isPlaying)it.pause() else it.start()}})}
    mime=="application/pdf"->{ParcelFileDescriptor.open(f,ParcelFileDescriptor.MODE_READ_ONLY).use {fd->PdfRenderer(fd).use {pdf->pdf.openPage(0).use {page->val scale=minOf(2f,1600f/maxOf(page.width,page.height));val bmp=Bitmap.createBitmap((page.width*scale).toInt(),(page.height*scale).toInt(),Bitmap.Config.ARGB_8888);bmp.eraseColor(Color.WHITE);page.render(bmp,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);body.addView(ImageView(this).apply {setImageBitmap(bmp);adjustViewBounds=true},LinearLayout.LayoutParams(-1,0,1f));body.addView(text("Page 1 of ${pdf.pageCount}",13f))}}}}
    mime.startsWith("text/")->{val scroll=ScrollView(this);scroll.addView(text(f.inputStream().bufferedReader().use {val chars=CharArray(12000);val n=it.read(chars);if(n<0)"Empty document" else String(chars,0,n)},16f));body.addView(scroll,LinearLayout.LayoutParams(-1,0,1f))}
    msg.isNull("fileid")->Unit
    else->body.addView(text("File received\n${msg.getString("filename")}\n${msg.getLong("size")/1024} KB\n\nThis file type has no in-app preview. You can save a copy to open with another app.",17f))
   }
  }catch(e:Exception){body.removeAllViews();body.addView(text("Preview unavailable. The file can still be saved."))}
  if(viewOnceId!=null)protection(root,body) else root.addView(body,LinearLayout.LayoutParams(-1,0,1f));if(viewOnceId==null)root.addView(button("Save a copy outside protection") {android.app.AlertDialog.Builder(this).setTitle("Export file?").setMessage("The saved copy will not be protected by GuardianLab. Other apps can open it.").setNegativeButton("Cancel",null).setPositiveButton("Save copy"){_,_->exportFile=f;startActivityForResult(Intent(Intent.ACTION_CREATE_DOCUMENT).apply {type=msg.optString("mime","application/octet-stream");addCategory(Intent.CATEGORY_OPENABLE);putExtra(Intent.EXTRA_TITLE,msg.getString("filename"))},21)}.show()});setContentView(root);renderProtection();if(viewOnceId!=null){if(foreground)monitor?.start();main.postDelayed(viewLimit,120000)}
 }
